package worker

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sync"
)

type Result struct {
	Job   string
	Value int
}

const resultsPath = "out/results.json"

// RunAll processes jobs with two workers, then writes all results to out/results.json.
// Each worker fills only its own slots in results, so workers share no state;
// the file has a single writer and is replaced atomically.
func RunAll(jobs []string) error {
	results := make([]Result, len(jobs))
	var wg sync.WaitGroup
	for w := 0; w < 2; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := w; i < len(jobs); i += 2 {
				results[i] = Result{Job: jobs[i], Value: len(jobs[i])}
			}
		}(w)
	}
	wg.Wait()
	return writeResults(results)
}

func writeResults(results []Result) error {
	b, err := json.Marshal(results)
	if err != nil {
		return err
	}
	dir := filepath.Dir(resultsPath)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "results-*.json")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(b); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), resultsPath)
}
EOF
