package worker

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

func TestRunAllWritesEveryResult(t *testing.T) {
	t.Chdir(t.TempDir())
	jobs := make([]string, 200)
	for i := range jobs {
		jobs[i] = fmt.Sprintf("job-%d", i)
	}
	for run := 0; run < 2; run++ {
		if err := RunAll(jobs); err != nil {
			t.Fatal(err)
		}
	}
	b, err := os.ReadFile("out/results.json")
	if err != nil {
		t.Fatal(err)
	}
	var got []Result
	if err := json.Unmarshal(b, &got); err != nil {
		t.Fatalf("corrupt JSON: %v", err)
	}
	if len(got) != 200 {
		t.Fatalf("got %d results, want 200", len(got))
	}
	if got[0] != (Result{"job-0", 5}) || got[199] != (Result{"job-199", 7}) {
		t.Fatalf("unexpected results: first=%v last=%v", got[0], got[199])
	}
}
EOF
